class PyroSerializableError(Exception):
    @staticmethod
    def to_dict(obj):
        serialized = {'__class__': obj.__class__.__name__,
                      'str': str(obj),
                      'traceback': 'should be already printed somewhere up!'}
        return serialized

    @classmethod
    def to_class(cls, _, serialized):
        return cls(cls.exception_string_with_remote_traceback(serialized))

    @staticmethod
    def exception_string_with_remote_traceback(serialized):
        return f"{serialized['str']}\nRemote traceback:\n{serialized['traceback']}"


class PyroRSIInternalError(PyroSerializableError):
    def __init__(self, internal_exception):
        super().__init__(str(internal_exception))
        self.internal_exception = internal_exception

    @staticmethod
    def to_dict(obj):
        serialized = super().to_dict(obj)
        serialized['internal_class'] = obj.internal_exception.__class__.__name__
        return serialized

    @classmethod
    def to_class(cls, _, serialized):
        internal_exception = globals().get(serialized['internal_class'], None) or \
            __builtins__.get(serialized['internal_class'], None)
        if internal_exception:
            return internal_exception(cls.exception_string_with_remote_traceback(serialized))
        serialized['str'] = f"Root cause: {serialized['internal_class']} - {serialized['str']}"
        return super().to_class(_, serialized)


class ReadPromptTimeoutError(Exception):
    def __init__(self, output_so_far):
        super().__init__(f"Did not receive prompt message. Output so far: {output_so_far}")
        self.output = output_so_far


class InvalidOutputError(PyroSerializableError):
    def __init__(self, output, pattern):
        super().__init__(f"Expected pattern: {pattern}, Received output: {repr(output)}")
        self.output = output
        self.pattern = pattern

    @staticmethod
    def to_dict(obj):
        serialized = super().to_dict(obj)
        serialized['pattern'] = obj.pattern
        serialized['output'] = obj.output
        return serialized

    @classmethod
    def to_class(cls, _, serialized):
        return cls(output=serialized['output'], pattern=serialized['pattern'])


class LoginFailedError(PyroSerializableError):
    pass


